<?php namespace App\Controllers; use App\Core\Controller; use App\Models\Car;
final class CarController extends Controller{public function index():void{$this->view('cars/index',['cars'=>Car::search($_GET),'filters'=>$_GET]);}public function show(string $id):void{$car=Car::find((int)$id);if(!$car){http_response_code(404);$this->view('errors/404');return;}$fav=auth()?Car::isFavorite((int)$id,(int)auth()['id']):false;$this->view('cars/show',compact('car','fav'));}public function create():void{$this->auth();$this->view('cars/form',['car'=>null]);}private function data():array{return['title'=>trim($_POST['title']??''),'brand'=>trim($_POST['brand']??''),'model'=>trim($_POST['model']??''),'year'=>(int)($_POST['year']??0),'price'=>(int)($_POST['price']??0),'mileage'=>(int)($_POST['mileage']??0),'transmission'=>$_POST['transmission']??'','fuel'=>$_POST['fuel']??'','color'=>trim($_POST['color']??''),'city'=>trim($_POST['city']??''),'description'=>trim($_POST['description']??''),'status'=>in_array($_POST['status']??'active',['active','sold'])?$_POST['status']:'active'];}private function valid(array $d):bool{return strlen($d['title'])>=8&&$d['year']>=1950&&$d['year']<=((int)date('Y')+1)&&$d['price']>0&&in_array($d['transmission'],['Manual','Otomatis'])&&in_array($d['fuel'],['Bensin','Diesel','Hybrid','Listrik'])&&strlen($d['description'])>=30;}private function uploads():array{$out=[];$files=$_FILES['images']??null;if(!$files)return$out;$finfo=new \finfo(FILEINFO_MIME_TYPE);for($i=0;$i<min(count($files['name']),5);$i++){if($files['error'][$i]===UPLOAD_ERR_NO_FILE)continue;if($files['error'][$i]!==UPLOAD_ERR_OK||$files['size'][$i]>2097152)continue;$mime=$finfo->file($files['tmp_name'][$i]);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??null;if(!$ext)continue;$name=bin2hex(random_bytes(16)).'.'.$ext;if(move_uploaded_file($files['tmp_name'][$i],dirname(__DIR__,2).'/public/uploads/'.$name))$out[]='uploads/'.$name;}return$out;}public function store():void{$u=$this->auth();$this->validateCsrf();$d=$this->data();if(!$this->valid($d)){flash('error','Data iklan belum valid. Isi semua kolom dan deskripsi minimal 30 karakter.');redirect('/mobil/tambah');}$images=$this->uploads();if(!$images){flash('error','Unggah minimal satu foto JPG, PNG, atau WebP maksimal 2 MB.');redirect('/mobil/tambah');}$d['user_id']=$u['id'];$id=Car::create($d,$images);flash('success','Iklan berhasil diterbitkan.');redirect('/mobil/'.$id);}public function edit(string $id):void{$u=$this->auth();$car=Car::find((int)$id);if(!$car||(int)$car['user_id']!==(int)$u['id']){http_response_code(403);exit('Akses ditolak');}$this->view('cars/form',compact('car'));}public function update(string $id):void{$u=$this->auth();$this->validateCsrf();$d=$this->data();if(!$this->valid($d)){flash('error','Data iklan belum valid.');redirect('/mobil/'.$id.'/edit');}Car::update((int)$id,(int)$u['id'],$d);flash('success','Iklan berhasil diperbarui.');redirect('/mobil/'.$id);}public function destroy(string $id):void{$u=$this->auth();$this->validateCsrf();Car::delete((int)$id,(int)$u['id']);flash('success','Iklan dihapus.');redirect('/dashboard');}public function favorite(string $id):void{$u=$this->auth();$this->validateCsrf();Car::toggleFavorite((int)$id,(int)$u['id']);redirect('/mobil/'.$id);}}
